"""Pure-function friction computation for `harness tune`.

Reads in-memory `SessionAnalysis` objects (produced by `analyse(parse_session(p))`)
and returns per-slash-command friction metrics. No file I/O. No network. Unit-testable.

The CLI handler (`harness.commands.tune`) is responsible for loading sessions
from disk; this module only does arithmetic on already-parsed sessions.
"""

from __future__ import annotations

import re
import statistics
from collections.abc import Iterable
from dataclasses import dataclass, field

from harness.analyse.aggregator import SessionAnalysis

# Keywords in human-intervention text that signal explicit dissatisfaction.
# Match is case-insensitive; whole-word boundaries to avoid false positives.
_BLOCKED_KEYWORDS_RE = re.compile(
    r"\b(blocked|redo|wrong|fix this|stop|cancel|undo|revert|don'?t|do not)\b",
    re.IGNORECASE,
)


@dataclass
class CommandFriction:
    """Friction metrics for one slash-command, aggregated across N sessions."""

    command: str
    runs: int = 0
    runs_with_intervention: int = 0
    total_interventions: int = 0
    runs_with_blocked_signal: int = 0
    runs_in_repeated_sessions: int = 0  # appeared ≥2× in same session
    durations_seconds: list[float] = field(default_factory=list)

    @property
    def mean_interventions_per_run(self) -> float:
        if self.runs == 0:
            return 0.0
        return self.total_interventions / self.runs

    @property
    def intervention_rate(self) -> float:
        if self.runs == 0:
            return 0.0
        return self.runs_with_intervention / self.runs

    @property
    def blocked_rate(self) -> float:
        if self.runs == 0:
            return 0.0
        return self.runs_with_blocked_signal / self.runs

    @property
    def repeat_rate(self) -> float:
        if self.runs == 0:
            return 0.0
        return self.runs_in_repeated_sessions / self.runs

    @property
    def mean_duration_seconds(self) -> float:
        if not self.durations_seconds:
            return 0.0
        return statistics.fmean(self.durations_seconds)

    @property
    def friction_score(self) -> float:
        """Composite ranking score. Higher = more friction."""
        return self.intervention_rate * 2 + self.repeat_rate + self.blocked_rate


@dataclass
class TuningThresholds:
    """User-tunable thresholds for hotspot classification."""

    mean_interventions_per_run: float = 2.0
    intervention_rate: float = 0.5
    blocked_rate: float = 0.2
    duration_multiplier: float = 2.0  # flag duration ≥ N× project median


@dataclass
class HotspotFlag:
    command: str
    reasons: list[str]
    metrics: CommandFriction


def compute_friction(sessions: Iterable[SessionAnalysis]) -> list[CommandFriction]:
    """Aggregate per-command friction across multiple sessions.

    Returns one `CommandFriction` per distinct slash-command observed across
    all sessions, with metrics summed across sessions.
    """
    sessions_list = list(sessions)
    by_command: dict[str, CommandFriction] = {}

    for sess in sessions_list:
        # Track which commands appeared in THIS session (to compute repeat_rate).
        commands_in_session: dict[str, int] = {}

        for phase in sess.phases:
            cmd = phase.slash_command
            if not cmd:
                # Skip the unnamed "Session boot" phase — not a command we can tune.
                continue

            commands_in_session[cmd] = commands_in_session.get(cmd, 0) + 1

            cf = by_command.setdefault(cmd, CommandFriction(command=cmd))
            cf.runs += 1

            num_interventions = len(phase.interventions)
            cf.total_interventions += num_interventions
            if num_interventions > 0:
                cf.runs_with_intervention += 1

            # Blocked signal — scan intervention text for friction keywords.
            for intervention in phase.interventions:
                text = intervention.text if hasattr(intervention, "text") else str(intervention)
                if _BLOCKED_KEYWORDS_RE.search(text):
                    cf.runs_with_blocked_signal += 1
                    break  # one match per run is enough

            cf.durations_seconds.append(phase.duration_seconds)

        # Second pass over THIS session: any command that ran ≥2× counts as repeat.
        for cmd, count in commands_in_session.items():
            if count >= 2 and cmd in by_command:
                # Each occurrence in the repeat run contributes to the repeat count.
                by_command[cmd].runs_in_repeated_sessions += count

    return sorted(by_command.values(), key=lambda c: c.friction_score, reverse=True)


def find_hotspots(
    frictions: list[CommandFriction],
    thresholds: TuningThresholds | None = None,
    project_median_duration: float | None = None,
) -> list[HotspotFlag]:
    """Apply threshold rules to flag hot-spot commands."""
    if thresholds is None:
        thresholds = TuningThresholds()

    flags: list[HotspotFlag] = []
    for cf in frictions:
        reasons: list[str] = []

        if cf.mean_interventions_per_run >= thresholds.mean_interventions_per_run:
            reasons.append(
                f"mean interventions/run = {cf.mean_interventions_per_run:.1f} "
                f"(≥ {thresholds.mean_interventions_per_run})"
            )
        if cf.intervention_rate >= thresholds.intervention_rate:
            reasons.append(
                f"intervention rate = {cf.intervention_rate * 100:.0f}% "
                f"(≥ {thresholds.intervention_rate * 100:.0f}%)"
            )
        if cf.blocked_rate >= thresholds.blocked_rate:
            reasons.append(
                f"blocked signal rate = {cf.blocked_rate * 100:.0f}% "
                f"(≥ {thresholds.blocked_rate * 100:.0f}%)"
            )
        if cf.repeat_rate > 0:
            reasons.append(
                f"repeat-within-session rate = {cf.repeat_rate * 100:.0f}% "
                f"(command ran more than once per session)"
            )
        if project_median_duration and project_median_duration > 0:
            ratio = cf.mean_duration_seconds / project_median_duration
            if ratio >= thresholds.duration_multiplier:
                reasons.append(
                    f"mean duration {cf.mean_duration_seconds:.0f}s "
                    f"= {ratio:.1f}× project median"
                )

        if reasons:
            flags.append(HotspotFlag(command=cf.command, reasons=reasons, metrics=cf))

    return flags


def project_median_duration(frictions: list[CommandFriction]) -> float:
    """Compute the project-wide median phase duration for ratio comparisons."""
    all_durations: list[float] = []
    for cf in frictions:
        all_durations.extend(cf.durations_seconds)
    if not all_durations:
        return 0.0
    return statistics.median(all_durations)


def render_recommendations(flags: list[HotspotFlag]) -> list[str]:
    """Generate human-readable recommendation strings from hotspot flags.

    Each recommendation names the command, its friction signals, and points
    at a likely skill-source path to inspect. Harness does NOT edit skill bodies;
    the team applies fixes manually.
    """
    recs: list[str] = []
    for flag in flags:
        cmd = flag.command
        # Map slash-command name to its skill source path. Best-effort guess —
        # actual path depends on the project's skill layout.
        skill_dir = cmd if cmd.startswith("arh-") else f"arh-{cmd}"
        skill_path = f"templates/base/skills/{skill_dir}/"
        reason_str = "; ".join(flag.reasons)

        rec = (
            f"`{cmd}` friction: {reason_str}. "
            f"Inspect skill source at `{skill_path}` — likely candidates "
            f"to revise: the Step 0 context-load (preconditions too strict?), "
            f"the rubric or template body (missing guidance triggering repeated "
            f"human correction?), and the final-summary verdict mapping "
            f"(unclear next-step instructions?)."
        )
        recs.append(rec)

    return recs
